    "source": "def naive_dijkstra(n: int, start: int, adj: list[list[tuple[int, float]]]) -> tuple[list[float], list[int]]:\n    \"\"\"Naive Dijkstra (non-negative weights) — complete Python reference. adj[u] = [(v, w), ...].\"\"\"\n    INF = float(\"inf\")\n    dist = [INF] * n\n    done = [False] * n\n    parent = [-1] * n\n    dist[start] = 0\n    for _ in range(n):\n        u = -1\n        best = INF\n        for i in range(n):\n            if not done[i] and dist[i] < best:\n                best = dist[i]\n                u = i\n        if u < 0 or best == INF:\n            break\n        done[u] = True\n        for v, w in adj[u]:\n            if dist[u] + w < dist[v]:\n                dist[v] = dist[u] + w\n                parent[v] = u\n    return dist, parent\n",
