    "source": "// Naive Dijkstra (non-negative weights) — complete C++17 reference. adj[u] = {(v, w), ...}.\n#include <limits>\n#include <utility>\n#include <vector>\n\nstd::pair<std::vector<double>, std::vector<int>> naiveDijkstra(int n, int start, const std::vector<std::vector<std::pair<int, double>>>& adj) {\n    const double INF = std::numeric_limits<double>::infinity();\n    std::vector<double> dist(n, INF);\n    std::vector<bool> done(n, false);\n    std::vector<int> parent(n, -1);\n    dist[start] = 0;\n    for (int iter = 0; iter < n; iter++) {\n        int u = -1;\n        double best = INF;\n        for (int i = 0; i < n; i++) {\n            if (!done[i] && dist[i] < best) {\n                best = dist[i];\n                u = i;\n            }\n        }\n        if (u < 0 || best == INF) break;\n        done[u] = true;\n        for (auto [v, w] : adj[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                parent[v] = u;\n            }\n        }\n    }\n    return {dist, parent};\n}\n",
