    "source": "package algorithms\n\nimport \"math\"\n\n// Arc is an outgoing edge u→V with weight W (adj[u] lists the arcs of u).\ntype Arc struct {\n\tV int\n\tW float64\n}\n\n// naiveDijkstra — naive Dijkstra (non-negative weights), complete Go reference.\nfunc naiveDijkstra(n, start int, adj [][]Arc) ([]float64, []int) {\n\tINF := math.Inf(1)\n\tdist := make([]float64, n)\n\tdone := make([]bool, n)\n\tparent := make([]int, n)\n\tfor i := range dist {\n\t\tdist[i], parent[i] = INF, -1\n\t}\n\tdist[start] = 0\n\tfor iter := 0; iter < n; iter++ {\n\t\tu := -1\n\t\tbest := INF\n\t\tfor i := 0; i < n; i++ {\n\t\t\tif !done[i] && dist[i] < best {\n\t\t\t\tbest = dist[i]\n\t\t\t\tu = i\n\t\t\t}\n\t\t}\n\t\tif u < 0 || best == INF {\n\t\t\tbreak\n\t\t}\n\t\tdone[u] = true\n\t\tfor _, e := range adj[u] {\n\t\t\tif dist[u]+e.W < dist[e.V] {\n\t\t\t\tdist[e.V] = dist[u] + e.W\n\t\t\t\tparent[e.V] = u\n\t\t\t}\n\t\t}\n\t}\n\treturn dist, parent\n}\n",
